<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { AuthStatus, BaseImages, Convert, CreateVM, DeleteVM, Health, Images, Login, Logout, MetricsStream, Operations, RuntimeStatus, SetAuthToken, VMAction, VMs } from './api'

const navItems = [
  { id: 'overview', label: 'Overview', icon: '▦' },
  { id: 'vms', label: 'Workloads', icon: '▣' },
  { id: 'convert', label: 'Images & Builds', icon: '◇' },
  { id: 'snapshots', label: 'Snapshots', icon: '◫' },
  { id: 'storage', label: 'Storage', icon: '▤' },
  { id: 'readiness', label: 'Host Readiness', icon: '▥' },
  { id: 'logs', label: 'Activity Logs', icon: '☷' },
  { id: 'settings', label: 'Settings', icon: '⚙' },
]

const state = reactive({
  tab: 'overview',
  authConfigured: false, authenticated: false, username: '', loginUsername: 'admin', loginPassword: '',
  token: '',
  source: 'alpine:latest', sourceType: 'oci', baseProfile: 'alpine', architecture: 'native',
  buildMethod: 'native', vcpus: 1, memoryMiB: 512, hostPort: 15432, guestPort: 5432,
  protocol: 'tcp', storageMode: 'ephemeral', persistentDisk: '', selectedVM: '', search: '',
})
const data = reactive({
  health: null, runtime: {}, metrics: { microvms: 0, runningVms: 0, images: 0, operations: 0, host: {} },
  vms: [], images: [], baseImages: [], operations: [], logs: [], message: '', loading: false,
})
const busy = ref(false)
let metricsSource
let refreshTimer

const selectedVM = computed(() => data.vms.find(vm => vm.id === state.selectedVM) || data.vms[0] || null)
const latestOperation = computed(() => data.operations.slice().sort((a, b) => new Date(b.updatedAt || b.createdAt) - new Date(a.updatedAt || a.createdAt))[0] || null)
const filteredVMs = computed(() => data.vms.filter(vm => `${vm.id} ${vm.imageReference || ''} ${vm.artifactDigest || ''}`.toLowerCase().includes(state.search.toLowerCase())))
const runtimeReady = computed(() => data.runtime.ready === true)
const hostChecks = computed(() => [
  ['Firecracker', data.runtime.installed ? 'Ready' : 'Missing'], ['Jailer', data.runtime.jailer || 'Unknown'],
  ['KVM', data.runtime.kvm || 'Unknown'], ['TAP Net', data.runtime.tap || 'Unknown'],
  ['Kernel', data.runtime.kernel || 'Unknown'], ['Rootfs', data.runtime.rootfs || 'Unknown'],
])
const pageTitle = computed(() => navItems.find(item => item.id === state.tab)?.label || 'Overview')

function errorText(error) { return String(error).replace(/^Error: /, '') }
function formatBytes(value = 0) { if (!value) return '0 B'; const units = ['B', 'KB', 'MB', 'GB', 'TB']; const i = Math.min(Math.floor(Math.log(value) / Math.log(1024)), units.length - 1); return `${(value / 1024 ** i).toFixed(i ? 1 : 0)} ${units[i]}` }
function ago(value) { if (!value) return '—'; const minutes = Math.max(0, Math.round((Date.now() - new Date(value).getTime()) / 60000)); return minutes < 1 ? 'Just now' : minutes < 60 ? `${minutes}m ago` : `${Math.round(minutes / 60)}h ago` }
function statusClass(value) { return String(value || 'unknown').toLowerCase().replace(/\s+/g, '-') }
function selectTab(tab) { state.tab = tab }
function startMetrics() { metricsSource?.close(); metricsSource = MetricsStream(metrics => { data.metrics = metrics }, () => {}) }
async function login() { busy.value = true; try { const result = await Login(state.loginUsername, state.loginPassword); state.authenticated = result.authenticated === true; state.username = result.username || state.loginUsername; state.loginPassword = ''; data.message = 'Signed in'; startMetrics(); await refresh() } catch (error) { data.message = errorText(error) } finally { busy.value = false } }
async function logout() { await Logout().catch(() => {}); metricsSource?.close(); state.authenticated = false; state.username = ''; data.message = 'Signed out' }
function saveToken() { SetAuthToken(state.token); data.message = state.token ? 'Legacy API token enabled for this browser session' : 'API token cleared'; startMetrics(); refresh() }
async function refresh() {
  data.loading = true
  try {
    data.runtime = await RuntimeStatus(); data.health = await Health()
    const [vms, images, baseImages, operations, logs] = await Promise.all([VMs(), Images(), BaseImages(), Operations(), fetchLogs()])
    data.vms = vms.vms || []; data.images = images.images || []; data.baseImages = baseImages.images || []; data.operations = operations.operations || []; data.logs = logs
    if (!state.selectedVM && data.vms[0]) state.selectedVM = data.vms[0].id
  } catch (error) { data.health = null; data.message = errorText(error) } finally { data.loading = false }
}
async function fetchLogs() { try { const response = await fetch('/api/v1/logs', { headers: state.token ? { Authorization: `Bearer ${state.token}` } : {} }); const result = await response.json(); return result.events || [] } catch { return [] } }
async function convert() { busy.value = true; try { const operation = await Convert(state.source, state.sourceType, state.baseProfile); data.message = `Conversion queued: ${operation.id}`; await refresh() } catch (error) { data.message = errorText(error) } finally { busy.value = false } }
async function createVM() {
  if (!latestOperation.value?.artifact?.digest) { data.message = 'Wait for a successful conversion before creating a workload'; return }
  busy.value = true
  try { const vm = await CreateVM(latestOperation.value.artifact.digest, Number(state.vcpus), Number(state.memoryMiB), latestOperation.value.request.source, [{ hostPort: Number(state.hostPort), guestPort: Number(state.guestPort), protocol: state.protocol }], state.storageMode, state.persistentDisk); state.selectedVM = vm.id; state.tab = 'vms'; data.message = 'Workload created. Press Start when ready.'; await refresh() } catch (error) { data.message = errorText(error) } finally { busy.value = false }
}
async function vmAction(id, action) { busy.value = true; try { await VMAction(id, action); data.message = `Workload ${action} requested`; await refresh() } catch (error) { data.message = errorText(error) } finally { busy.value = false } }
async function deleteVM(id) { if (!window.confirm('Delete this microVM and its managed files?')) return; busy.value = true; try { await DeleteVM(id); state.selectedVM = ''; data.message = 'Workload deleted'; await refresh() } catch (error) { data.message = errorText(error) } finally { busy.value = false } }
function chooseVM(vm) { state.selectedVM = vm.id; state.tab = 'vms' }
onMounted(async () => { SetAuthToken(state.token); try { const auth = await AuthStatus(); state.authConfigured = auth.configured === true; state.authenticated = auth.authenticated === true; state.username = auth.username || ''; } catch (error) { data.message = errorText(error) } if (!state.authConfigured || state.authenticated) { startMetrics(); await refresh(); refreshTimer = window.setInterval(refresh, 6000) } })
onBeforeUnmount(() => { metricsSource?.close(); if (refreshTimer) window.clearInterval(refreshTimer) })
</script>

<template>
  <section v-if="state.authConfigured && !state.authenticated" class="login-shell">
    <div class="login-card panel">
      <div class="brand-block login-brand"><div class="brand-mark">⌁</div><div><h1>Firecracker<br />Studio</h1><p>Remote microVM console</p></div></div>
      <span class="section-kicker">SECURE SIGN IN</span>
      <h2>Open your Studio workspace</h2>
      <p class="login-copy">Sign in once to manage images, microVMs, logs, networking, storage, and operations from this server.</p>
      <form @submit.prevent="login">
        <label>ADMIN USERNAME<input v-model="state.loginUsername" autocomplete="username" required /></label>
        <label>ADMIN PASSWORD<input v-model="state.loginPassword" type="password" autocomplete="current-password" required /></label>
        <button class="primary-button" :disabled="busy">{{ busy ? 'Signing in…' : 'Sign in to Studio' }}</button>
      </form>
      <p v-if="data.message" class="login-error">{{ data.message }}</p>
    </div>
  </section>
  <div v-else class="studio-shell">
    <aside class="side-nav">
      <div class="brand-block"><div class="brand-mark">⌁</div><div><h1>Firecracker<br />Studio</h1><p><span class="dot success"></span> Host: {{ data.health ? 'Connected' : 'Offline' }}</p></div></div>
      <button class="new-vm-button" @click="selectTab('convert')"><span>＋</span> New MicroVM</button>
      <nav class="nav-list" aria-label="Main navigation">
        <button v-for="item in navItems" :key="item.id" class="nav-item" :class="{ active: state.tab === item.id }" @click="selectTab(item.id)"><span class="nav-icon">{{ item.icon }}</span><span>{{ item.label }}</span><b v-if="item.id === 'vms' && data.vms.length">{{ data.vms.length }}</b></button>
      </nav>
      <div class="sidebar-footer">v1.4.2 · local control server</div>
    </aside>

    <main class="studio-main">
      <header class="top-nav"><div class="top-title"><strong>Firecracker Studio</strong><div class="search-box"><span>⌕</span><input v-model="state.search" placeholder="Search resources..." /></div></div><div class="top-actions"><span v-if="state.username" class="api-pill">{{ state.username }}</span><span class="api-pill"><span class="dot success"></span> API: {{ data.health ? 'ACTIVE' : 'OFFLINE' }}</span><button class="icon-button" title="Refresh" @click="refresh">↻</button><button class="avatar-button" title="Settings" @click="selectTab('settings')">◉</button><button v-if="state.authenticated" class="icon-button" title="Sign out" @click="logout">⇥</button></div></header>
      <div v-if="data.message" class="toast" :class="{ 'toast-error': data.message.includes('HTTP') || data.message.includes('failed') || data.message.includes('Offline') }" role="status"><span>{{ data.message }}</span><div class="toast-actions"><button v-if="!data.health" class="text-button" @click="refresh">Retry connection</button><button aria-label="Dismiss notification" @click="data.message = ''">×</button></div></div>

      <section v-if="state.tab === 'overview'" class="page-content overview-page">
        <section class="readiness-banner panel"><div class="section-kicker">HOST READINESS &amp; CAPACITY</div><div class="readiness-row"><span v-for="check in hostChecks" :key="check[0]" class="readiness-item"><span class="dot" :class="check[1].startsWith('Ready') || check[1].startsWith('present') || check[1].startsWith('ready') ? 'success' : 'warning'"></span><code>{{ check[0] }}</code></span><span class="divider"></span><span class="capacity-item">▣ <code>Disk: {{ data.metrics.host?.diskPercent ? `${Math.round(100 - data.metrics.host.diskPercent)}% Free` : 'Unknown' }}</code></span><span class="capacity-item">▤ <code>Mem: {{ data.metrics.host?.memoryPercent ? `${Math.round(100 - data.metrics.host.memoryPercent)}% Free` : 'Unknown' }}</code></span></div></section>
        <div v-if="!data.health" class="offline-panel panel"><div class="offline-icon">!</div><div><strong>Studio cannot reach the control server</strong><p>The dashboard is available, but live VM data and actions are paused until the Go API is running.</p><code>Start the backend, then retry the connection.</code></div><button class="primary-button compact" @click="refresh">Retry connection</button></div><div v-if="!runtimeReady" class="warning-banner panel"><strong>Host is not ready to start microVMs.</strong><span>{{ data.runtime.message || 'Review the Host Readiness page for actionable diagnostics.' }}</span><button class="text-button" @click="selectTab('readiness')">View diagnostics →</button></div><section v-if="!data.vms.length && !data.images.length" class="onboarding panel"><div class="onboarding-copy"><span class="section-kicker">FIRST RUN</span><h2>Launch your first microVM in three steps</h2><p>Studio keeps the hard Firecracker details behind a simple, guided workflow.</p></div><div class="onboarding-steps"><button class="onboarding-step" :class="{ done: runtimeReady }" @click="selectTab('readiness')"><span>1</span><b>Check host readiness</b><small>{{ runtimeReady ? 'Ready to continue' : 'Verify KVM, kernel, and rootfs' }}</small></button><button class="onboarding-step" @click="selectTab('convert')"><span>2</span><b>Convert an image</b><small>Turn Docker/OCI input into a bootable artifact</small></button><button class="onboarding-step" @click="selectTab('convert')"><span>3</span><b>Create a workload</b><small>Choose resources, storage, and ports</small></button></div></section>
        <div class="overview-grid"><section class="metric-grid"><div class="metric-card"><span class="section-kicker">TOTAL MICROVMS</span><strong>{{ data.metrics.microvms ?? data.vms.length }}</strong><span class="metric-watermark">▥</span></div><div class="metric-card"><span class="section-kicker">RUNNING <i class="dot success"></i></span><strong>{{ data.metrics.runningVms ?? data.vms.filter(vm => vm.state === 'running').length }}</strong></div><div class="metric-card"><span class="section-kicker">PAUSED <i class="dot warning"></i></span><strong>{{ data.vms.filter(vm => vm.state === 'paused').length }}</strong></div><div class="metric-card"><span class="section-kicker">AVAILABLE IMAGES</span><strong>{{ data.metrics.images ?? data.images.length }}</strong></div><div class="metric-card wide-metric"><span class="section-kicker">SNAPSHOT STORAGE</span><strong>— <small>GB used</small></strong><div class="progress purple"><span style="width: 34%"></span></div></div><div class="metric-card wide-metric"><div class="resource-line"><span>HOST CPU</span><b>{{ data.metrics.host?.cpuPercent || 0 }}%</b></div><div class="progress cyan"><span :style="{ width: `${data.metrics.host?.cpuPercent || 0}%` }"></span></div><div class="resource-line"><span>HOST MEMORY</span><b>{{ data.metrics.host?.memoryPercent || 0 }}%</b></div><div class="progress cyan"><span :style="{ width: `${data.metrics.host?.memoryPercent || 0}%` }"></span></div></div></section><section class="quick-actions panel"><div class="quick-actions-heading"><div><span class="section-kicker">NEXT BEST ACTION</span><h2>Quick Actions</h2></div><span class="action-hint">{{ !data.health ? 'Waiting for API' : runtimeReady ? 'Ready to run' : 'Setup required' }}</span></div><button class="quick-action primary-action" @click="selectTab('convert')"><span class="quick-icon">＋</span><span><b>Create Workload</b><small>Deploy a new microVM instance</small></span><strong>→</strong></button><button class="quick-action" @click="selectTab('convert')"><span class="quick-icon">⇄</span><span><b>Convert Image</b><small>OCI/Ext4 format conversion</small></span></button><button class="quick-action" @click="selectTab('snapshots')"><span class="quick-icon">◴</span><span><b>Restore Snapshot</b><small>Boot from saved state</small></span></button><button class="quick-action" @click="selectTab('readiness')"><span class="quick-icon">♢</span><span><b>Check Host Readiness</b><small>Run system diagnostics</small></span></button></section></div>
        <section class="activity-panel panel"><div class="panel-header"><h2>Recent Activity</h2><button class="text-button" @click="selectTab('logs')">View All Logs</button></div><div v-if="data.logs.length || data.vms.length || data.operations.length" class="activity-list"><div v-for="event in data.logs.slice(-3).reverse()" :key="event" class="activity-row"><span class="activity-icon">›</span><span>{{ event }}</span><time>recent</time></div><div v-for="vm in data.vms.slice(0, 2)" :key="vm.id" class="activity-row"><span class="activity-icon cyan-icon">▣</span><span>Workload <code>{{ vm.id.slice(0, 12) }}</code> is {{ vm.state }}</span><time>{{ ago(vm.updatedAt) }}</time></div></div><div v-else class="empty-state">No activity yet. Convert an image to begin.</div></section>
      </section>

      <section v-if="state.tab === 'vms'" class="page-content workloads-page"><div class="page-heading"><div><h2>Workloads</h2><p>{{ data.vms.length }} active microVMs in current namespace.</p></div><button class="outline-button">≡ Filter</button></div><div class="workload-split"><section class="workload-table panel"><div class="table-toolbar"><div><span class="section-kicker">MICROVM INVENTORY</span><strong>{{ filteredVMs.length }} workload{{ filteredVMs.length === 1 ? '' : 's' }}</strong></div><button class="outline-button" @click="refresh">↻ Refresh</button></div><div class="table-head"><span>NAME</span><span>STATUS</span><span>IMAGE</span><span>RESOURCES</span><span>LAST UPDATED</span></div><button v-for="vm in filteredVMs" :key="vm.id" class="workload-row" :class="{ selected: selectedVM?.id === vm.id }" @click="chooseVM(vm)"><span class="workload-name"><span class="vm-icon">▣</span><b>{{ vm.imageReference || vm.id.slice(0, 12) }}</b></span><span><em class="status-pill" :class="statusClass(vm.state)"><i class="dot"></i>{{ vm.state }}</em></span><code>{{ vm.imageReference || vm.artifactDigest?.slice(0, 16) }}</code><span>{{ vm.vcpus || 1 }} vCPU<br />{{ vm.memoryMiB || 512 }} MB</span><span>{{ ago(vm.updatedAt) }}</span></button><div v-if="!filteredVMs.length" class="empty-state">No workloads match your search.</div></section><aside v-if="selectedVM" class="detail-drawer panel"><div class="drawer-title"><div><span class="vm-icon large">▣</span><div><h3>{{ selectedVM.imageReference || selectedVM.id.slice(0, 12) }}</h3><p>microVM ID: {{ selectedVM.id.slice(0, 12) }}</p></div></div><button class="close-button" @click="state.selectedVM = ''">×</button></div><div class="lifecycle-actions"><button :disabled="busy || selectedVM.state === 'running'" @click="vmAction(selectedVM.id, 'start')">▷<small>START</small></button><button :disabled="busy || !['running', 'paused'].includes(selectedVM.state)" @click="vmAction(selectedVM.id, 'stop')">□<small>STOP</small></button><button :disabled="busy || selectedVM.state !== 'running'" @click="vmAction(selectedVM.id, 'pause')">Ⅱ<small>PAUSE</small></button><button :disabled="busy || selectedVM.state !== 'paused'" @click="vmAction(selectedVM.id, 'resume')">▷<small>RESUME</small></button><button :disabled="busy" @click="vmAction(selectedVM.id, 'start')">↻<small>RESTART</small></button></div><div class="drawer-actions"><button>◴<small>SNAP</small></button><button class="delete-action" @click="deleteVM(selectedVM.id)">▥<small>DELETE</small></button></div><div class="detail-card"><div class="section-kicker">SPECIFICATIONS</div><div class="spec-grid"><div><span>CPU Allocation</span><b>{{ selectedVM.vcpus || 1 }} vCPU</b></div><div><span>Memory Allocation</span><b>{{ selectedVM.memoryMiB || 512 }} MB</b></div></div><label>Image Digest<input readonly :value="selectedVM.artifactDigest" /></label><label>Kernel Path<input readonly :value="selectedVM.kernelPath || 'runtime default'" /></label><label>Rootfs Path<input readonly :value="selectedVM.rootfsPath || 'artifact managed'" /></label></div><div class="detail-card"><div class="section-kicker">CONFIGURATION</div><div class="config-row"><span>Persistent Storage<small>{{ selectedVM.storageMode || 'ephemeral' }}</small></span><b>{{ selectedVM.storageMode === 'persistent' ? 'ON' : 'OFF' }}</b></div><div class="config-row"><span>Port Mappings<small>Host : Guest</small></span><code>{{ selectedVM.portMappings?.[0] ? `${selectedVM.portMappings[0].hostPort}:${selectedVM.portMappings[0].guestPort}` : 'none' }}</code></div><div class="config-row"><span>Socket Health<small>API communication</small></span><strong class="healthy">✓ Healthy</strong></div></div><div class="detail-card boot-card"><div class="section-kicker">▣ BOOT LOGS</div><pre>{{ selectedVM.logs?.join('\n') || 'No boot logs yet.' }}</pre></div></aside><aside v-if="!selectedVM" class="detail-drawer panel drawer-empty"><span class="large-symbol">▣</span><h3>Select a workload</h3><p>Choose a microVM from the list to inspect resources, lifecycle actions, storage, and boot logs.</p></aside></div></section>\n\n      <section v-if="state.tab === 'convert'" class="page-content builds-page"><div class="page-heading"><div><h2>Images &amp; Builds</h2><p>Manage container images and convert them into bootable Firecracker artifacts.</p></div></div><section class="info-banner panel"><span class="info-icon">i</span><div><h3>Artifact Conversion Pipeline</h3><p>Docker and OCI images are input packages. Studio converts the container image into a bootable kernel/rootfs artifact before starting a microVM.</p></div></section><div class="builds-grid"><section class="conversion-card panel"><h3>New Conversion Job</h3><form @submit.prevent="convert"><label>REFERENCE<input v-model="state.source" placeholder="e.g., nginx:latest" /></label><label>SOURCE TYPE<select v-model="state.sourceType"><option value="oci">OCI Image Registry</option><option value="docker">Docker Image</option><option value="dockerfile">Dockerfile</option><option value="archive">OCI Archive</option></select></label><div class="two-inputs"><label>ARCHITECTURE<select v-model="state.architecture"><option>native</option><option>x86_64</option><option>aarch64</option></select></label><label>BASE PROFILE<select v-model="state.baseProfile"><option>alpine</option><option>debian</option><option>ubuntu</option></select></label></div><label>BUILD METHOD<select v-model="state.buildMethod"><option value="native">Native · Direct extraction</option><option value="buildkit">BuildKit · Planned adapter</option><option value="aoci">AOCI · Planned adapter</option></select></label><button class="primary-button" :disabled="busy || !state.source">{{ busy ? 'Converting…' : '⇄ Convert an OCI/Docker image' }}</button></form></section><section class="jobs-card panel"><div class="panel-header"><h3>Recent Conversion Jobs</h3><button class="text-button">≡ Filter</button></div><div class="job-head"><span>STATUS</span><span>IMAGE REF</span><span>ARCH / PROFILE</span><span>ACTIONS</span></div><div v-for="operation in data.operations.slice().reverse()" :key="operation.id" class="job-row"><span><em class="status-pill" :class="statusClass(operation.state)">{{ operation.state }}</em><small v-if="operation.error">{{ operation.error }}</small></span><code>{{ operation.request?.source || '—' }}</code><span>{{ operation.request?.architecture || 'native' }} / {{ operation.request?.baseProfile || 'alpine' }}</span><button v-if="operation.state === 'succeeded'" class="small-button" @click="state.tab = 'vms'">▷ Create Workload</button><button v-else class="icon-button">×</button></div><div v-if="!data.operations.length" class="empty-state">No conversion jobs yet.</div></section></div></section>

      <section v-if="state.tab === 'readiness'" class="page-content"><div class="page-heading"><div><h2>Host Readiness</h2><p>Check every prerequisite before starting a microVM.</p></div><button class="primary-button compact" @click="refresh">↻ Run checks again</button></div><section class="panel readiness-detail"><div v-for="check in hostChecks" :key="check[0]" class="diagnostic-row"><span class="diagnostic-status" :class="check[1].startsWith('Ready') || check[1].startsWith('present') || check[1].startsWith('ready') ? 'success' : 'warning'">●</span><div><b>{{ check[0] }}</b><p>{{ check[1] }}</p></div><span class="diagnostic-action">{{ check[1].startsWith('Ready') || check[1].startsWith('present') || check[1].startsWith('ready') ? 'Available' : 'Review' }}</span></div></section></section>
      <section v-if="state.tab === 'logs'" class="page-content"><div class="page-heading"><div><h2>Activity Logs</h2><p>Recent control-plane and lifecycle events.</p></div></div><section class="panel logs-panel"><pre>{{ data.logs.join('\n') || 'No activity recorded yet.' }}</pre></section></section>
      <section v-if="state.tab === 'snapshots' || state.tab === 'storage' || state.tab === 'settings'" class="page-content"><div class="page-heading"><div><h2>{{ pageTitle }}</h2><p>{{ state.tab === 'snapshots' ? 'Snapshot catalog and restore workflows.' : state.tab === 'storage' ? 'Persistent and ephemeral workload storage.' : 'Studio control-plane configuration.' }}</p></div></div><section class="panel empty-state large-empty"><span class="large-symbol">{{ state.tab === 'snapshots' ? '◫' : state.tab === 'storage' ? '▤' : '⚙' }}</span><h3>{{ pageTitle }} workspace</h3><p>The backend lifecycle foundation is ready. This screen keeps the Stitch layout and is ready for the next API-backed module.</p></section></section>
    </main>
  </div>
</template>
